from scipy.optimize import brentq
def m4(a):
  x=0.5
  for _ in range(3000): x=a*x*(1-x)
  for _ in range(60):
    y=x;d=1
    for _ in range(4): d*=a*(1-2*y); y=a*y*(1-y)
    x=x-(y-x)/(d-1)
  y=x;d=1
  for _ in range(4): d*=a*(1-2*y); y=a*y*(1-y)
  assert abs(y-x)<1e-12
  return d
a3=brentq(lambda a: m4(a)+1,3.5,3.55,xtol=1e-13)
a2=1+6**.5
assert abs(a3-3.5441)<1e-4
assert abs((a2-3)/(a3-a2)-4.75)<0.01
import numpy as np
assert abs(a2-3.4495)<1e-4 and abs(1+8**.5-3.828)<1e-3
def n3(a):
  P=np.poly1d([-a,a,0]); g=P(P(P))
  r=(g-np.poly1d([1,0])).r
  return sum(1 for z in r if abs(z.imag)<1e-7)
assert n3(1+8**.5-0.01)==2 and n3(1+8**.5+0.01)==8

blocks.body:
For nice $f$ (say smooth with $f$ and its derivatives decaying faster than any power of $x$):

- derivative: $\widehat{f'}(\xi) = 2\pi i\xi\,\hat f(\xi)$, by integration by parts;
- multiplication by $x$: $\widehat{-2\pi i x f}(\xi) = \hat f\,'(\xi)$, by differentiating under the integral;
- convolution: $(f * g)(x) = \int f(y)g(x - y)\,dy$ has $\widehat{f*g} = \hat f\,\hat g$.

The first rule is what makes the transform useful for differential equations. Multiplication by $2\pi i\xi$ is algebra, so an equation such as $u'' - u = -h$ becomes $(-4\pi^2\xi^2 - 1)\hat u = -\hat h$, and $\hat u = \hat h/(1 + 4\pi^2\xi^2)$. Recognising $\frac{1}{1+4\pi^2\xi^2}$ as the transform of $\tfrac12 e^{-|x|}$ and using the convolution rule backwards gives the solution $u = \tfrac12 e^{-|x|} * h$ that decays at infinity.

