u={0:F(1)}
for n in range(1,11):
  v={}
  for j,a in u.items():
    v[j-1]=v.get(j-1,0)+a/2; v[j+1]=v.get(j+1,0)+a/2
  u=v
  if n==4: assert {j:a for j,a in u.items() if a}=={-4:F(1,16),-2:F(4,16),0:F(6,16),2:F(4,16),4:F(1,16)}
  assert sum(a*j*j for j,a in u.items())==n
  assert all(u.get(j,0)==(F(comb(n,(n+j)//2),2**n) if (n+j)%2==0 and abs(j)<=n else 0) for j in range(-n,n+1))
