import numpy as np
def run(C,N=100,steps=600):
    x=np.linspace(0,1,N+1)
    u0=np.sin(np.pi*x)
    u1=u0.copy()
    u1[1:-1]=u0[1:-1]+0.5*C*C*(u0[:-2]-2*u0[1:-1]+u0[2:])
    for _ in range(steps):
        u2=np.zeros_like(u0)
        u2[1:-1]=2*u1[1:-1]-u0[1:-1]+C*C*(u1[:-2]-2*u1[1:-1]+u1[2:])
        u0,u1=u1,u2
    return np.abs(u1).max()
assert run(1.0)<1.01 and run(1.1)>1e3
L,c,h=1.0,1.0,0.1
def fodd(z):
    z=np.mod(z,2*L)
    y=np.where(z<=L,z,2*L-z)
    s=np.where(z<=L,1.0,-1.0)
    return s*np.where(y<=L/2,2*h*y/L,2*h*(L-y)/L)
def series(x,t,M=20001):
    n=np.arange(1,M)
    return np.sum(8*h/(n**2*np.pi**2)*np.sin(n*np.pi/2)*np.sin(n*np.pi*x/L)*np.cos(n*np.pi*c*t/L))
for x,t in [(0.3,0.1),(0.5,0.37),(0.8,1.3)]:
    dal=(fodd(np.array(x-c*t))+fodd(np.array(x+c*t)))/2
    assert abs(dal-series(x,t))<2e-5
